test("frozen carried and as of tree scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "contact": " Ada@x ", "tags": "c"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "3", "tags": "b, a"})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "3", "contact": "ADA@X"})).toBeNull();
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "4.00", "start": "2026-02-20", "end": "2026-04-30", "day": "1"}));
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "7.77"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "delete")).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "restore")).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-02-10"})).toBe(true);
  await ui.setToday(pg_uma, "2026-04-01");
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
